function pkValue(f){return f.value||({not_reported:'Not reported in checked source',not_curated:'Not yet curated'}[f.status]||'Not established');}
function pkEvidence(label,f){return `<div class="pk-evidence-row"><strong>${h(label)}</strong><span>${h(pkValue(f))}</span>${f.context?`<p>${h(f.context)}</p>`:''}<div>${f.sourceIds.map(sourceLink).join(' · ')}</div></div>`;}
function renderPharmacokinetics(d){
 const p=d.pharmacokinetics,active=mode==='ckd'?'ihd':mode,removal=p.dialysability[active];
 if(p.status==='not_curated')return `<details class="pk-panel pk-empty"><summary>Pharmacokinetics & dialysability <span>Awaiting curation</span></summary><p>Half-life, volume of distribution, protein binding and removal by IHD, PD, CRRT and SLED have not yet been curated for this drug. Missing data do not mean zero binding, no removal or no renal adjustment.</p></details>`;
 const card=(label,f,extra='')=>`<div class="pk-card"><div class="pk-label">${h(label)}</div><strong>${h(pkValue(f))}</strong>${extra}</div>`;
 const renal=p.renalHalfLife;
 const renalHtml=`<div class="pk-renal"><span>${renal.basis==='guideline_esrf_column'?'ESRF reference':'Renal impairment'}</span> ${h(pkValue(renal))}${renal.basis==='guideline_esrf_column'?' †':''}</div>`;
 return `<section class="pk-panel" aria-label="Pharmacokinetics and dialysability"><div class="pk-heading"><h3>Pharmacokinetics & dialysability</h3><span>ADULT SOURCE SUMMARY</span></div><div class="pk-grid">${card('Reference half-life',p.halfLife,renalHtml)}${card('Volume of distribution · Vd',p.volumeOfDistribution)}${card('Plasma protein binding',p.proteinBinding)}${card('Removal by '+modeNames[active],removal)}</div><p class="pk-caveat">Reference values depend on analyte, formulation, route and clinical state. Half-life is not the dosing interval. Vd in L and L/kg are distinct.${renal.basis==='guideline_esrf_column'?' † ESRF values are from the UKKA reference table; they are not measured on-dialysis half-lives.':''}</p>${p.notes?`<p class="pk-note">${h(p.notes)}</p>`:''}${removal.context?`<p class="pk-note"><b>${h(modeNames[active])} evidence.</b> ${h(removal.context)}</p>`:''}<details class="pk-details"><summary>Removal by each RRT modality & field evidence</summary><div class="pk-rrt-table-wrap"><table class="pk-rrt-table"><thead><tr><th>Setting</th><th>Removal statement</th><th>Evidence</th></tr></thead><tbody>${['ihd','pd','crrt','sled'].map(k=>{const f=p.dialysability[k];return `<tr><th>${h(modeNames[k])}</th><td>${h(pkValue(f))}${f.context?`<small>${h(f.context)}</small>`:''}</td><td>${f.sourceIds.map(sourceLink).join('<br>')}</td></tr>`;}).join('')}</tbody></table></div>${pkEvidence('Reference half-life',p.halfLife)}${pkEvidence('Renal impairment / ESRF half-life',p.renalHalfLife)}${pkEvidence('Volume of distribution',p.volumeOfDistribution)}${pkEvidence('Protein binding',p.proteinBinding)}<p class="pk-review">PK source check: ${h(p.sourceCheckedAt)} · Independent clinical approval pending. “Unknown”, “not reported” and “not yet curated” are distinct. No post-dialysis supplement is calculated from these values.</p></details></section>`;
}
